/* Acessos às funções existentes. Não lê nem grava bases do sistema. */
(()=>{'use strict';const $=id=>document.getElementById(id),main=document.querySelector('main');if(!main||$('martins-acessos'))return;
const css=document.createElement('style');css.textContent=`#martins-acessos{margin:0 0 22px;padding:20px;border:1px solid #dfd4bb;border-radius:18px;background:#fff;box-shadow:0 5px 20px #30220c08;color:#172234}#martins-acessos h2{font-size:21px;font-weight:850;line-height:1.25;margin:0}#martins-acessos .ma-kicker{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:#85662e;font-weight:800;margin:0 0 6px}#martins-acessos .ma-intro{font-size:13px;color:#546174;margin:8px 0 16px}#martins-acessos .ma-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}#martins-acessos .ma-card{display:flex;flex-direction:column;align-items:flex-start;text-align:left;gap:7px;padding:16px;background:#f7f8fa;border:1px solid #e3e7ed;border-radius:12px;color:#172234;min-height:125px;cursor:pointer;min-width:0}#martins-acessos .ma-card:hover{border-color:#ad873c;background:#fffaf0}#martins-acessos .ma-card:focus-visible,.ma-dialog-nav button:focus-visible{outline:3px solid #ad873c;outline-offset:3px}#martins-acessos .ma-card svg{width:23px;height:23px;color:#8a692e}#martins-acessos .ma-title{font-size:15px;font-weight:800}#martins-acessos .ma-copy{font-size:12px;line-height:1.4;color:#566175}#martins-acessos .ma-status{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px;font-size:11px;color:#5c6471}#martins-acessos .ma-status span{padding:5px 8px;background:#f0f2f5;border-radius:6px}#martins-acessos .ma-help{margin-top:12px;font-size:12px;line-height:1.5;color:#566175}#martins-acessos .ma-help summary{cursor:pointer;font-weight:700;color:#765b28}.ma-dialog-nav{display:flex;flex-wrap:wrap;gap:5px;margin:10px 0 16px;padding:8px;background:#f4f0e7;border-radius:9px}.ma-dialog-nav button{min-height:44px;font-size:13px!important;margin:0!important}.ma-dialog-nav button[aria-pressed=true]{background:#31291a!important;box-shadow:inset 0 -3px #e1b85d}#mp-panel>summary,#mcf-panel>summary{font-size:16px;font-weight:800;padding:15px 10px;background:#f8f5ef;border:1px solid #ded4bd;border-radius:9px;cursor:pointer;margin:12px 0}#ma-feedback{font-size:12px;color:#8a3b14;margin-top:8px}@media(max-width:650px){#martins-acessos{padding:14px;border-radius:13px}#martins-acessos h2{font-size:19px}#martins-acessos .ma-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}#martins-acessos .ma-card{padding:12px;min-height:126px}#martins-acessos .ma-title{font-size:14px}.ma-dialog-nav button{flex:1 1 110px}}@media print{#martins-acessos,.ma-dialog-nav{display:none!important}}`;css.textContent+=`#martins-acessos{border-color:#e2e8f0}#martins-acessos .ma-kicker{color:#b45309}#martins-acessos .ma-card{background:#0f172a;border-color:#334155;color:#f8fafc}#martins-acessos .ma-card:hover{background:#1e293b;border-color:#f59e0b}#martins-acessos .ma-title{color:#f8fafc}#martins-acessos .ma-copy{color:#cbd5e1}#martins-acessos .ma-card svg{color:#fbbf24}.ma-dialog-nav{background:#f1f5f9}.ma-dialog-nav button{background:#0f172a!important;color:#f8fafc!important}.ma-dialog-nav button[aria-pressed=true]{background:#f59e0b!important;color:#020617!important}#mp-panel>summary,#mcf-panel>summary{background:#f8fafc;border-color:#cbd5e1;color:#0f172a}#ma-drawer-access{padding:8px;border-top:1px solid #e2e8f0;margin-top:8px}#ma-drawer-access h4{font-size:10px;font-weight:900;color:#64748b;text-transform:uppercase;margin:8px}#ma-drawer-access button{width:100%;min-height:46px;display:flex;align-items:center;gap:10px;padding:10px;border-radius:10px;text-align:left;color:#334155;font-size:12px;font-weight:700}#ma-drawer-access button:hover{background:#f1f5f9}#ma-drawer-access svg{width:20px;height:20px;color:#d97706}`;document.head.append(css);
const nav=document.createElement('nav');nav.id='martins-acessos';nav.setAttribute('aria-label','Acessos às funções do sistema');nav.innerHTML='<p class="ma-kicker">Gestão da obra</p><h2>O que você precisa fazer?</h2><p class="ma-intro">Acesse as ferramentas diretamente, sem procurar no menu.</p><div class="ma-grid"></div><div class="ma-status"><span>Dados locais neste navegador</span><span>Supabase remoto desativado nos testes</span></div><details class="ma-help"><summary>O que já posso testar?</summary><p>Planejamento por dia, semana e mês; equipes próprias e terceirizadas; indisponibilidades; réplica de frequência com revisão; atividades e fotos do RDO; conferência das divergências com justificativa e CSV.</p><p>Planejar não registra presença. Revisar uma divergência não altera os lançamentos. Para conferir outro dia, escolha a data na Frequência ou o período na Conferência.</p></details><p id="ma-feedback" role="status" aria-live="polite"></p>';main.prepend(nav);
const icon=path=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true">'+path+'</svg>';
let auditOpened=false;
function navigate(section,sub){if(typeof window.navegarParaSecao!=='function')throw Error('A navegação ainda está carregando. Tente novamente.');window.navegarParaSecao(section,sub);}
function activate(kind){try{$('ma-feedback').textContent='';if(kind==='rdo'){navigate('novo');$('view-novo')?.scrollIntoView({block:'start',behavior:'smooth'});return;}navigate('colaboradores','ponto');if(kind==='frequencia'){$('ponto-data-filtro')?.scrollIntoView({block:'center',behavior:'smooth'});return;}const dialog=$('mj-dialog');if(!dialog)throw Error('O painel ainda está carregando. Tente novamente.');if(!dialog.open)$('mj-open').click();const planning=$('mp-panel'),audit=$('mcf-panel');planning.open=kind==='planejamento';audit.open=kind==='conferencia';if(kind==='conferencia'&&!auditOpened){$('mcf-day').click();auditOpened=true;}const target=kind==='planejamento'?planning:audit;requestAnimationFrame(()=>{target.scrollIntoView({block:'start',behavior:'smooth'});target.querySelector('summary')?.focus();});updateTabs();}catch(e){$('ma-feedback').textContent=e.message;}}
const cards=[['frequencia','Frequência diária','Presenças, faltas e horas por obra.',icon('<path d="M8 3v4m8-4v4M4 10h16M5 5h14v16H5z"/><path d="m9 15 2 2 4-4"/>')],['planejamento','Planejamento e equipes','Dia, semana, mês e réplica revisável.',icon('<path d="M4 4h16v16H4zM4 9h16M9 9v11M15 9v11"/><path d="M8 2v4m8-4v4"/>')],['rdo','RDO e fotos','Atividades, equipe e registro fotográfico.',icon('<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7m-7 4h7"/>')],['conferencia','Conferir divergências','Planejado × Frequência × RDO.',icon('<path d="M5 4h14v16H5zM8 8h8M8 12h4m-4 4h4"/><path d="m14 14 2 2 4-4"/>')]];
for(const [kind,title,copy,svg] of cards){const button=document.createElement('button');button.type='button';button.id='ma-'+kind;button.className='ma-card';button.innerHTML=svg+'<span class="ma-title">'+title+'</span><span class="ma-copy">'+copy+'</span>';button.onclick=()=>activate(kind);nav.querySelector('.ma-grid').append(button);}
function installDrawer(){if($('ma-drawer-access'))return;const drawerList=$('drawer-menu-lateral')?.querySelector('.overflow-y-auto');if(drawerList){const group=document.createElement('div');group.id='ma-drawer-access';const title=document.createElement('h4');title.textContent='Planejamento, frequência e conferência';group.append(title);for(const [kind,label,copy,svg] of cards){const b=document.createElement('button');b.type='button';b.id='ma-menu-'+kind;b.innerHTML=svg+'<span>'+label+'</span>';b.onclick=()=>{window.fecharDrawerMenu?.();activate(kind);};group.append(b);}drawerList.prepend(group);}}
const originalDrawer=window.reorganizarDrawerLateralDefinitivo;if(typeof originalDrawer==='function')window.reorganizarDrawerLateralDefinitivo=function(...args){const result=originalDrawer.apply(this,args);installDrawer();return result;};document.addEventListener('DOMContentLoaded',installDrawer);installDrawer();
const tabs=document.createElement('nav');tabs.className='ma-dialog-nav';tabs.setAttribute('aria-label','Navegar no painel de jornada');for(const [id,label] of [['dia','Dia e obra'],['planejamento','Planejamento e equipes'],['conferencia','Conferir divergências']]){const b=document.createElement('button');b.type='button';b.id='ma-tab-'+id;b.textContent=label;b.onclick=()=>{if(id!=='dia')activate(id);else{$('mp-panel').open=false;$('mcf-panel').open=false;$('mj-day').scrollIntoView({block:'center',behavior:'smooth'});$('mj-day').focus();updateTabs();}};tabs.append(b);}$('mj-dialog')?.querySelector('h2')?.insertAdjacentElement('afterend',tabs);
function updateTabs(){for(const kind of ['planejamento','conferencia'])$('ma-tab-'+kind)?.setAttribute('aria-pressed',String(Boolean($(kind==='planejamento'?'mp-panel':'mcf-panel')?.open)));$('ma-tab-dia')?.setAttribute('aria-pressed',String(!$('mp-panel')?.open&&!$('mcf-panel')?.open));}
for(const id of ['mp-panel','mcf-panel'])$(id)?.addEventListener('toggle',updateTabs);updateTabs();
})();
